 if($('#slideexport'))$('#slideexport').onclick=async()=>{try{const d=await api('/api/export/slides',{method:'POST',body:{clientId,title:$('#slidetitle').value,content:$('#slidecontent').value}});$('#slideout').innerHTML=`<a class="btn primary" href="${d.url}">Baixar PPTX (${d.slides} slides)</a>`}catch(e){$('#slideout').textContent=e.message}};
